#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum TnsType {
    NChar = 1,
    Number = 2,
    BInteger = 3,
    Float = 4,
    NullStr = 5,
    VarNum = 6,
    Pdn = 7,
    Long = 8,
    Varchar = 9,
    LongVarChar = 94,
    Rowid = 11,
    Date = 12,
    VarRaw = 15,
    BFloat = 21,
    BDouble = 22,
    /// IB 浮点族（go-ora IBFloat=100 / IBDouble=101）——Oracle 返回
    /// BINARY_FLOAT/BINARY_DOUBLE 时实际用的是这两个 TNS 类型（真机 11g 实测
    /// CAST(1.5 AS BINARY_DOUBLE) 的 describe 类型为 101）
    IBFloat = 100,
    IBDouble = 101,
    Raw = 23,
    LongRaw = 24,
    Char = 96,
    RefCursor = 102,
    /// XMLType（TNS_DATA_TYPE_EXT_NAMED 108 / INT_NAMED 109 的 XMLType 形态）
    OciXmlType = 108,
    XmlType = 109,
    Clob = 112,
    Blob = 113,
    BFile = 114,
    ResultSet = 116,
    Json = 119,
    Vector = 127,
    TimeStampDty = 180,
    TimeStampTzDty = 181,
    IntervalYmDty = 182,
    IntervalDsDty = 183,
    Timestamp = 187,
    TimestampTz = 188,
    IntervalYm = 189,
    IntervalDs = 190,
    URowid = 208,
    Boolean = 0xFC,
    Unknown(u8),
}

impl From<u8> for TnsType {
    fn from(val: u8) -> Self {
        match val {
            1 => TnsType::NChar,
            2 => TnsType::Number,
            3 => TnsType::BInteger,
            4 => TnsType::Float,
            5 => TnsType::NullStr,
            6 => TnsType::VarNum,
            7 => TnsType::Pdn,
            8 => TnsType::Long,
            9 => TnsType::Varchar,
            11 => TnsType::Rowid,
            12 => TnsType::Date,
            15 => TnsType::VarRaw,
            21 => TnsType::BFloat,
            22 => TnsType::BDouble,
            100 => TnsType::IBFloat,
            101 => TnsType::IBDouble,
            23 => TnsType::Raw,
            24 => TnsType::LongRaw,
            94 => TnsType::LongVarChar,
            96 => TnsType::Char,
            102 => TnsType::RefCursor,
            108 => TnsType::OciXmlType,
            109 => TnsType::XmlType,
            112 => TnsType::Clob,
            113 => TnsType::Blob,
            114 => TnsType::BFile,
            116 => TnsType::ResultSet,
            119 => TnsType::Json,
            127 => TnsType::Vector,
            180 => TnsType::TimeStampDty,
            181 => TnsType::TimeStampTzDty,
            182 => TnsType::IntervalYmDty,
            183 => TnsType::IntervalDsDty,
            187 => TnsType::Timestamp,
            188 => TnsType::TimestampTz,
            189 => TnsType::IntervalYm,
            190 => TnsType::IntervalDs,
            208 => TnsType::URowid,
            0xFC => TnsType::Boolean,
            other => TnsType::Unknown(other),
        }
    }
}

impl From<TnsType> for u8 {
    fn from(t: TnsType) -> Self {
        match t {
            TnsType::NChar => 1,
            TnsType::Number => 2,
            TnsType::BInteger => 3,
            TnsType::Float => 4,
            TnsType::NullStr => 5,
            TnsType::VarNum => 6,
            TnsType::Pdn => 7,
            TnsType::Long => 8,
            TnsType::Varchar => 9,
            TnsType::Rowid => 11,
            TnsType::Date => 12,
            TnsType::VarRaw => 15,
            TnsType::BFloat => 21,
            TnsType::BDouble => 22,
            TnsType::IBFloat => 100,
            TnsType::IBDouble => 101,
            TnsType::Raw => 23,
            TnsType::LongRaw => 24,
            TnsType::LongVarChar => 94,
            TnsType::Char => 96,
            TnsType::RefCursor => 102,
            TnsType::OciXmlType => 108,
            TnsType::XmlType => 109,
            TnsType::Clob => 112,
            TnsType::Blob => 113,
            TnsType::BFile => 114,
            TnsType::ResultSet => 116,
            TnsType::Json => 119,
            TnsType::Vector => 127,
            TnsType::TimeStampDty => 180,
            TnsType::TimeStampTzDty => 181,
            TnsType::IntervalYmDty => 182,
            TnsType::IntervalDsDty => 183,
            TnsType::Timestamp => 187,
            TnsType::TimestampTz => 188,
            TnsType::IntervalYm => 189,
            TnsType::IntervalDs => 190,
            TnsType::URowid => 208,
            TnsType::Boolean => 0xFC,
            TnsType::Unknown(x) => x,
        }
    }
}
